  "M38-3-4": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">池塘边原来有一些蜻蜓</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">飞走6只后</span></div>",
  "M38-4-1": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">乐乐有 10 块巧克力</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">月亮有 6 块巧克力</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">乐乐给月亮几块后</span></div>",
  "M38-4-2": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">小明有 14 支铅笔</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">小刚有 8 支铅笔</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">小明给小刚几支后</span></div>",
  "M38-4-3": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">小红给小芳 2 朵红花后</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">两人的红花同样多</span></div>",
  "M38-4-4": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">哥哥给弟弟 3 颗糖后</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">两人的糖同样多</span></div>",
  "M38-5-1": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">9 + 8  = ？</span></div>",
  "M38-5-2": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">9 + 2 + 6 = ？</span></div>",
  "M38-5-3": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">8 + 4 + 3 = ？</span></div>",
  "M38-6-1": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">在 9 + ( ) = 8 + 6 中</span></div>",
  "M38-6-2": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">在 7 + 8 = ( ) + 6 中</span></div>",
  "M38-6-3": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">在 8 + 7 = 9 + ( ) 中</span></div>",
  "M38-6-4": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">三个小朋友拍球</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">小明拍了 8 下</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">小红拍了 7 下</span></div>",
  "M38-7-1": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">小红买了一套画笔用去 9 元</span></div>",
  "M38-7-2": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">公共汽车上原来有一些乘客</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">没有人上车</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">到站后下车 8 人</span></div>",
  "M38-7-3": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">花丛中有 9 只黄蝴蝶和 7 只白蝴蝶</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">飞走了 5 只</span></div>",
  "M38-7-4": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">果盘里有 8 个红苹果</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">妈妈又放进去 5 个青苹果</span><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">乐乐吃了 2 个</span></div>",
  "M38-8-1": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">送出6个苹果</span></div>",
  "M38-8-2": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">甲有12块糖</span></div>",
  "M38-8-3": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">计算8+5</span></div>",
  "M39-2-1": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">从0数到10的整数个数 ○ 10里面含有的“一”的个数</span></div>",
  "M39-2-2": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">8 + 7 ○ 9 + 6</span></div>",
  "M39-2-3": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">17 - 7 ○ 5 + 5</span></div>",
  "M39-2-4": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">2个十 ○ 1个十和9个一</span></div>",
  "M39-3-1": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">小明今天从第 5 页读到第 12 页</span></div>",
  "M39-3-2": "<div class=\"flex flex-wrap justify-center gap-3 p-3 border border-slate-300 rounded-xl bg-white text-sm text-slate-800\"><span class=\"px-3 py-2 border border-slate-300 rounded-lg\">整数字 5 和整数字 12 之间</span></div>",
